const LG_ORDER=["terms","privacy","cookies","your-data","risk","data","liability","refunds","about","accessibility"];
function legalDoc(){const m=/^#\/legal\/([a-z-]+)/.exec(location.hash);return m&&LEGAL[m[1]]?m[1]:null}
function legalRender(){let el=document.getElementById("pv-legal");if(!el)return;const d=legalDoc();
const nav=`<nav aria-label="Legal">${LG_ORDER.filter(k=>LEGAL[k]).map(k=>`<a href="#/legal/${k}" class="${k===d?"on":""}">${LEGAL[k][0]}</a>`).join("")}</nav>`;
const body=d?LEGAL[d][1]():`<h1>Legal</h1>${LG_META()}<div class="riskbox"><b>Risk warning:</b> trading CFDs, FX and crypto carries a high risk of losing money. Nothing on this site is financial advice. <a href="#/legal/risk">Read the risk disclaimer</a>.</div><ul>${LG_ORDER.filter(k=>LEGAL[k]).map(k=>`<li><a href="#/legal/${k}">${LEGAL[k][0]}</a></li>`).join("")}</ul>`;
el.innerHTML=`<div class="pgw"><div class="lgl">${nav}<article class="lgldoc vcard">${body}</article></div></div>`;
if(d&&LEGAL[d][2]){try{LEGAL[d][2](el.querySelector("article"))}catch(e){console.error(e)}}
if(d)document.title=LEGAL[d][0]+" \u00b7 Vektor Terminal";el.scrollTop=0}
PAGE_HOOK.legal={enter:legalRender,sub:legalRender};
function vtFooterBuild(){const w=document.querySelector(".wrap");if(!w)return;
if(!document.getElementById("pv-legal")){const pv=document.createElement("div");pv.className="pv";pv.id="pv-legal";const last=[...w.querySelectorAll(".pv")].pop();if(last)last.after(pv);else w.appendChild(pv)}
const old=w.querySelector("footer.vfoot");if(old)old.remove();const f=document.createElement("footer");f.className="vfoot";
f.innerHTML=`<span class="risk"><b>Risk warning:</b> trading CFDs, FX and crypto carries a high risk of losing money. Nothing here is financial advice. <a href="#/legal/risk">Risk disclaimer</a></span>`+LG_ORDER.filter(k=>k!=="risk"&&LEGAL[k]).map(k=>`<a href="#/legal/${k}">${LEGAL[k][0]}</a>`).join("")+`<button type="button" class="lnk" id="vft_ck" onclick="vtBanner(true)">Cookie settings</button>`;
w.appendChild(f)}
